#include <iostream>

int main() {
    int km, heure;
    std::cin >> km >> heure;
    int tarif;
    if (km <= 3) {
        tarif = 200;
    } else if (km <= 8) {
        tarif = 400;
    } else {
        tarif = 700;
    }
    if (heure >= 22 || heure <= 5) {
        tarif = tarif + 100;
    }
    std::cout << "Tarif : " << tarif << " FCFA\n";
    return 0;
}
